xpath.script:
if (window.Capacitor && window.Capacitor.getPlatform() !== 'web') {
    var viewport = document.querySelector('meta[name="viewport"]');
    if (viewport) {
        viewport.setAttribute('content', 'width=device-width, initial-scale=1, user-scalable=no, viewport-fit=cover');
    }

    document.documentElement.style.opacity = '0';
    document.documentElement.style.backgroundColor = '#ffffff';

    document.addEventListener('DOMContentLoaded', function() {
        document.documentElement.style.transition = 'opacity 0.25s ease-in-out';
        document.documentElement.style.opacity = '1';
    });

    setTimeout(function() {
        if (document.documentElement.style.opacity === '0') {
            document.documentElement.style.transition = 'opacity 0.25s ease-in-out';
            document.documentElement.style.opacity = '1';
        }
    }, 1000);
}
